        vars['read_state'] = 'ok'
        last4 = vars.get('sel_last4') or str(d.get('cardNumberLast4') or '')
        name = vars.get('sel_name') or (d.get('productName') or '').strip()
        intro = 'Sonu ' + digits(last4) + ' ile biten ' + (name + ' kartınıza ait' if name else 'kartınıza ait')
        tdy = today()
        sd = pdate(d.get('statementDate')); ld = pdate(d.get('lastPayDate'))
        vars['stmt_date'] = d.get('statementDate') or ''
        parts = []
        blocks = {}
        for cc in ('TL', 'USD', 'EUR', 'GBP'):
            bl = d.get('debt' + cc)
            if isinstance(bl, dict) and bl: blocks[cc] = bl
        def has(cc):
            bl = blocks.get(cc)
            if not bl: return False
            r = num(bl.get('remainingDebt')); s = num(bl.get('statementDebt'))
            if cc == 'TL':
                return r is not None and r > 0
            return (s is not None and s > 0) and (r is None or r > 0) or (r is not None and r > 0)
        owing = [cc for cc in ('TL', 'USD', 'EUR', 'GBP') if has(cc)]
        vars['stmt_currency'] = owing[0] if owing else 'TL'
        if not sd:
            parts.append(intro + ' kesilmiş bir ekstre bulunmadığından ekstre borcunuz bulunmamaktadır.')
        elif str(d.get('statementPaymentStatus')) == 'NO_DEBT' or not owing:
            tl = blocks.get('TL') or {}
            s = intro.replace(' kartınıza ait', ' kartınızın').replace('ile biten kartınızın', 'ile biten kartınızın') + ' ' + sdate(d.get('statementDate')) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
            tot = num(tl.get('totalDebt'))
            if tot is not None and tot > 0:
                s += ' Gelecek dönemler dahil toplam borcunuz ' + amt(tot, 'TL') + '.'
            nd = d.get('nextLastPayDate') or d.get('lastPayDate')
            if nd: s += ' Son ödeme tarihiniz ' + sdate(nd) + ' olacaktır.'
            parts.append(s)
        else:
            if tdy and sd and tdy == sd:
                parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
            first = True
            for cc in owing:
                bl = blocks[cc]
                pre = (intro + ' ' + sdate(d.get('statementDate')) + ' tarihinde kesilen ekstre ') if first else ''
                first = False
                X = num(bl.get('statementDebt')) or 0; Z = num(bl.get('minPayment')) or 0
                Y = num(bl.get('remainingDebt')) or 0; T = num(bl.get('remainingMinPayment')) or 0
                if cc == 'TL':
                    if T > 0 and T >= Z:
                        s = 'Türk Lirası borcunuz ' + amt(X, 'TL') + ', ödenmesi gereken minimum tutar ' + amt(Z, 'TL') + '.'
                    elif T <= 0:
                        s = 'Türk Lirası borcunuz ' + amt(X, 'TL') + ', kalan toplam borcunuz ' + amt(Y, 'TL') + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                    else:
                        s = 'Türk Lirası borcunuz ' + amt(X, 'TL') + ', ödenmesi gereken minimum tutar ' + amt(Z, 'TL') + ', kalan toplam borcunuz ' + amt(Y, 'TL') + ', kalan minimum ödeme tutarınız ' + amt(T, 'TL') + '.'
                else:
                    full = CUR[cc][0]
                    s = full + ' borcunuz ' + amt(X, cc) + ', kalan toplam borcunuz ' + amt(Y, cc) + ', ödenmesi gereken minimum tutar ' + amt(Z, cc) + '.'
                parts.append(pre + s if pre else s)
            clear = [CUR[cc][0] for cc in ('TL', 'USD', 'EUR', 'GBP') if cc in blocks and cc not in owing]
            if clear:
                if len(clear) == 1: parts.append(clear[0] + ' borcunuz bulunmamaktadır.')
                else: parts.append(', '.join(clear[:-1]) + ' ve ' + clear[-1] + ' borcunuz bulunmamaktadır.')
            tl = blocks.get('TL') or {}
            ra = num(tl.get('remainAutomaticPaymentAmount'))
            if tdy and ld and tdy > ld and str(d.get('automaticPaymentFlag')) == 'Y' and ra and ra > 0:
                parts.append('Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar ' + amt(ra, 'TL') + '.')
            if tdy and ld and tdy == ld:
                parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            elif tdy and ld and tdy > ld:
                tot = num(tl.get('totalDebt'))
                s = 'Son ödeme tarihiniz olan ' + sdate(d.get('lastPayDate')) + ' geçmiştir.'
                if tot is not None and tot > 0: s += ' Toplam borcunuz ' + amt(tot, 'TL') + '.'
                parts.append(s)
            elif ld:
                parts.append('Borçlarınız için son ödeme tarihiniz ' + sdate(d.get('lastPayDate')) + '.')
        vars['reading'] = ' '.join(parts)
        e, erc, eb = code_of('em')
        ed = eb.get('data') if isinstance(eb.get('data'), dict) else {}
        email = str(ed.get('ibanEmail') or '').strip()
        ctype = str(ed.get('communicationType') or '')
        if not ed or erc not in ('1', ''):
            vars['email_state'] = 'error'; email = ''
        elif not email or ctype.lower() == 'phone':
            vars['email_state'] = 'none'; email = ''
        else:
            vars['email_state'] = 'ok'
        vars['email'] = email
        if vars['email_state'] in ('ok', 'error'):
            vars['offer'] = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim. Başka bir işlem yapmak ister misiniz?'
        else:
            vars['offer'] = 'Hesap kesim tarihinizi değiştirebilirim. Başka bir işlem yapmak ister misiniz?'
        multi = vars.get('card_state') == 'multi'
        vars['after_q'] = 'another' if multi else 'offer'
        vars['reading_full'] = vars['reading'] + ' ' + ('Başka bir kartınızın borcunu öğrenmek ister misiniz?' if multi else vars['offer'])
        vars['next_action'] = ''
except Exception as ex:
    vars['read_state'] = 'error'
